source("h.R")
u <- function(s) { Encoding(s) <- "UTF-8"; s }
w <- function(n, x, ...) writeBin(npy_encode(x, ...), sprintf("out/b_%s.npy", n))
w("v", 1:3); w("m31", matrix(1:3, 3, 1)); w("m13", matrix(1:3, 1, 3)); w("m11", matrix(1, 1, 1)); w("m23", matrix(1:6 + 0, 2)); w("a234", array(1:24, 2:4))
w("m23C", matrix(1:6 + 0, 2), order = "C"); w("e03", matrix(0, 0, 3)); w("e30", matrix(0, 3, 0)); w("e0", numeric()); w("a111", array(1L, c(1,1,1)))
w("a213", array(1:6, c(2,1,3))); w("a123", array(1:6, c(1,2,3))); w("a231", array(1:6, c(2,3,1)))
w("s", c("a", u("\xe6\x97\xa5\xe6\x9c\xac"), "")); w("S", c("a", "bcd"), dtype = "|S"); w("l", c(TRUE, FALSE)); w("z", c(1+2i, NA)); w("r", as.raw(0:255))
w("d", as.Date(c("1969-12-31", NA, "2262-04-12"))); w("t", as.POSIXct(c(-1.5, 1e9, NA), origin = "1970-01-01", tz = "UTC"))
w("tns", as.POSIXct(c(-1.5, 1e9), origin = "1970-01-01", tz = "UTC"), unit = "ns"); w("ts", as.POSIXct(c(-2, 1e9), origin = "1970-01-01", tz = "UTC"), unit = "s")
w("dm", as.difftime(c(-3, 5), units = "mins")); w("dw", as.difftime(c(1, NA), units = "weeks")); w("dus", as.difftime(c(0.000001, -2.5), units = "secs"), dtype = "<m8[us]")
w("f4", c(0.1, -1e30, NaN, Inf), dtype = "<f4"); w("f2", c(0.1, 65504, 1e-8, -0), dtype = "<f2"); w("u8", c(0, 2^53, 2^63), dtype = "<u8"); w("i1", c(-128L, 127L), dtype = "|i1")
w("c8", c(1.1+2.2i), dtype = "<c8"); w("i64", bit64::as.integer64(c("-9223372036854775807", "9223372036854775807")))
w("U0", c("", ""), dtype = "<U0"); w("nai", c(1L, NA), na = "allow"); w("nal", c(TRUE, NA), na = "allow") 
w("naf", c(1L, NA), na = "allow", dtype = "<f8"); w("ms", matrix(c("a","bb","ccc","d"), 2)); w("u4", c(0, 4294967295), dtype = "<u4")
w("lat", u("caf\xc3\xa9"), dtype = "|S", encoding = "latin1")
